_BY_ID = {str(item["id"]): item for item in A1_FILAMENT_CATALOG}
_GENERIC_BY_TYPE = {
    str(item["material_type"]).upper(): item
    for item in A1_FILAMENT_CATALOG
    if item["vendor"] == "Generic"
}


def filament_profile(filament_id: str) -> dict[str, Any] | None:
    item = _BY_ID.get(str(filament_id or "").strip())
    return dict(item) if item is not None else None


def generic_filament_profile(material_type: str) -> dict[str, Any] | None:
    item = _GENERIC_BY_TYPE.get(str(material_type or "").strip().upper())
    return dict(item) if item is not None else None


def catalog_payload() -> list[dict[str, Any]]:
    return [dict(item) for item in A1_FILAMENT_CATALOG]